import json

# Systematic analysis of the problem
def analyze_gaps():
    """Analyze the relationship between val, base_row, and gap"""

    # Demo: h=13, base_row=9
    # val=2 -> top=5, gap=4
    # val=8 -> top=6, gap=3

    test_cases = [
        ("demo", 13, 9, {"2": 4, "8": 3}),
    ]

    print("Analyzing gap patterns:")
    for name, h, base, gaps in test_cases:
        print(f"\n{name}: h={h}, base={base}")
        for val, expected_gap in gaps.items():
            print(f"  val={val}: expected gap={expected_gap}")

analyze_gaps()

# Try many formulas and see which one fits best
def find_formula():
    results = []

    for val, expected_gap in [{"2": 4, "8": 3}]:
        # Test various formulas
        h = 13
        base = 9

        for i in range(-5, 10):
            for j in range(-5, 10):
                def make_formula(i, j):
                    return lambda v, h=h, b=base: abs(v*i + h*j + b - base) + 1

                f = make_formula(i, j)
                pred = f(val, h, base)
                if abs(pred - expected_gap) < 0.1:
                    results.append((i, j, pred))

    print("\nPotential formulas found:")
    for i, j, pred in results[:5]:
        print(f"  gap = abs({val}*{i} + {h}*{j} + {base} - {base}) + 1 = {pred}")

find_formula()

